export const css: string = "/*\n * Tempra design tokens: the one place values live (TEMPRA-8). Deliberately plain for now, close to\n * browser defaults; the design pass (TEMPRA-1) changes values here and both the app and the site\n * follow. Light and dark come from the user's system through light-dark().\n */\n:root {\n  color-scheme: light dark;\n\n  /* Color */\n  --tempra-color-text: light-dark(#111111, #e8e8e8);\n  --tempra-color-muted: light-dark(#555555, #a8a8a8);\n  --tempra-color-bg: light-dark(#ffffff, #121212);\n  --tempra-color-link: light-dark(#0000ee, #8ab4f8);\n  --tempra-color-link-visited: light-dark(#551a8b, #c58af9);\n  --tempra-color-border: light-dark(#cccccc, #444444);\n  --tempra-color-code-bg: light-dark(#f4f4f4, #1e1e1e);\n\n  /* Type */\n  --tempra-font-body: system-ui, sans-serif;\n  --tempra-font-mono: ui-monospace, monospace;\n  --tempra-font-size: 1rem;\n  --tempra-line-height: 1.5;\n  --tempra-measure: 70ch;\n\n  /* Space */\n  --tempra-space-1: 0.25rem;\n  --tempra-space-2: 0.5rem;\n  --tempra-space-3: 1rem;\n  --tempra-space-4: 2rem;\n\n  /* Shape */\n  --tempra-radius: 0;\n}\n\n/* Element defaults for every page of the app and the site; values come from tokens.css. */\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  padding: var(--tempra-space-3);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-font-size);\n  line-height: var(--tempra-line-height);\n}\n\na {\n  color: var(--tempra-color-link);\n}\n\na:visited {\n  color: var(--tempra-color-link-visited);\n}\n\ncode,\npre,\nkbd,\nsamp {\n  font-family: var(--tempra-font-mono);\n}\n\nhr {\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\ntable {\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  padding: var(--tempra-space-1) var(--tempra-space-2);\n  text-align: left;\n  vertical-align: top;\n}\n\nimg {\n  max-width: 100%;\n}\n\n/*\n * How a rendered concept reads: the markdown body of a concept, in the app now and wherever\n * concepts are shown later (the site, inline MCP Apps views). Scoped to .prose.\n */\n.prose {\n  max-width: var(--tempra-measure);\n}\n\n.prose pre {\n  overflow-x: auto;\n  padding: var(--tempra-space-2);\n  background: var(--tempra-color-code-bg);\n  border-radius: var(--tempra-radius);\n}\n\n.prose blockquote {\n  margin-left: 0;\n  padding-left: var(--tempra-space-3);\n  border-left: 3px solid var(--tempra-color-border);\n  color: var(--tempra-color-muted);\n}\n\n.prose table th,\n.prose table td {\n  border: 1px solid var(--tempra-color-border);\n}\n\n.prose .footnotes {\n  font-size: 0.9em;\n  color: var(--tempra-color-muted);\n}\n\n/*\n * The concept reader (Wordgard, TEMPRA-11). Wordgard themes itself through --wg-* variables set\n * on its own element; these map them to Tempra's tokens and keep the body as plain as the rest of\n * the page. The selectors are one step more specific than Wordgard's injected theme.\n */\ndiv.body > * {\n  --wg-panel-color: var(--tempra-color-bg);\n  --wg-border-color: var(--tempra-color-border);\n  --wg-highlight-color: var(--tempra-color-link);\n  --wg-dialog-font: inherit;\n  border: 0;\n}\n\ndiv.body wg-content {\n  padding: 0;\n}\n\n.tooltip {\n  max-width: 32rem;\n  padding: var(--tempra-space-1) var(--tempra-space-2);\n  border: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n}\n\n.prose a.broken {\n  text-decoration-line: line-through;\n}\n\n.prose pre.raw,\n.prose code.raw {\n  color: var(--tempra-color-muted);\n}\n\n.toc {\n  padding-left: var(--tempra-space-3);\n}\n\n.toc .depth-1 {\n  margin-left: var(--tempra-space-3);\n}\n\n.toc .depth-2 {\n  margin-left: var(--tempra-space-4);\n}\n";

